  baseCharacterKey: jIn.baseCharacterKey ?? baseRes.baseCharacterKey ?? baseRes.characterKey ?? null,
  baseCharacterUrl: jIn.baseCharacterUrl ?? baseRes.baseCharacterUrl ?? baseRes.characterUrl ?? null,

  poseRefKey: jIn.poseRefKey ?? poseRes.poseRefKey ?? poseRes.key ?? null,
  poseRefUrl: jIn.poseRefUrl ?? poseRes.poseRefUrl ?? poseRes.url ?? null,
  poseRefName: jIn.poseRefName ?? poseRes.poseRefName ?? poseRes.name ?? null,

  // optional hair reference (keep if available)
  hairKey: jIn.hairKey ?? hairRes.hairKey ?? null,
  hairUrl: jIn.hairUrl ?? hairRes.hairUrl ?? null,

  // breadcrumb
  __meta: {
    ...(jIn.__meta || {}),
    qahandoff: { runIx, itemIndex: ix, stripped: true }
  }
};

// we rebuild 'keep' so heavy keys from jIn aren't present; nothing else to delete.
// Output: NO binaries.
global.gc?.();
return { json: keep, binary: {} };
